# AS4 IR Tool - QuickResponse

function Get-As4QuickTasks {
    @(
    # ---- System ----
    (N 'hostname' 'Hostname' 'Sys' 'hostname.exe' @() 'Prints the computer name.' 'Anchors every artifact to a host.' -Quick $true)
    (N 'systeminfo' 'System Information (systeminfo)' 'Sys' 'systeminfo.exe' @() 'OS version/build, install date, boot time, hotfixes, domain, NICs.' 'Baseline of OS, patch level and install/boot dates.' -Timeout 240 -Quick $true)
    (S 'datetime' 'Date, Time and UTC' 'Sys' { $n=Get-Date; $tz=[TimeZoneInfo]::Local; [pscustomobject]@{ LocalTime=$n.ToString('o'); UtcTime=$n.ToUniversalTime().ToString('o'); TimeZone=$tz.Id; UtcOffset=$tz.GetUtcOffset($n).ToString(); DaylightSaving=$tz.IsDaylightSavingTime($n) } } 'Records target local time, UTC time and time zone at collection.' 'Required to interpret and normalise all other timestamps; compare against a trusted clock to note skew.' -Quick $true)
    (S 'osinfo' 'OS Details and Install Info' 'Sys' { Get-CimInstance Win32_OperatingSystem | Select-Object CSName,Caption,Version,BuildNumber,OSArchitecture,InstallDate,LastBootUpTime,RegisteredUser,Organization,WindowsDirectory,SystemDirectory,TotalVisibleMemorySize,FreePhysicalMemory } 'OS caption, build, architecture, install date, boot time.' 'Identifies artifact formats available and system age.' -Quick $true)
    (S 'computerinfo' 'Computer and Domain Membership' 'Sys' { Get-CimInstance Win32_ComputerSystem | Select-Object Name,Domain,PartOfDomain,DomainRole,Workgroup,Manufacturer,Model,TotalPhysicalMemory,UserName,NumberOfProcessors } 'Computer model, RAM size, domain/workgroup membership and console user.' 'Domain context for lateral movement scoping; RAM size for memory acquisition planning.' -Quick $true)
    (S 'uptime' 'System Uptime' 'Sys' { $b=(Get-CimInstance Win32_OperatingSystem).LastBootUpTime; [pscustomobject]@{ LastBootLocal=$b.ToString('o'); LastBootUtc=$b.ToUniversalTime().ToString('o'); Uptime=((Get-Date)-$b).ToString() } } 'Last boot time and uptime.' 'Dates reboot-sensitive evidence and volatility of memory.' -Quick $true)
    (S 'envvars' 'Environment Variables' 'Sys' { Get-ChildItem Env: | Select-Object Name,Value } 'Environment of the collecting process (user and machine).' 'Reveals proxies, odd PATH entries, temp locations.' -Sensitive $true)
    (S 'drives' 'Mounted Volumes and Drives' 'Sys' { Get-CimInstance Win32_LogicalDisk | Select-Object DeviceID,DriveType,VolumeName,FileSystem,Size,FreeSpace,ProviderName } 'Logical drives, size and free space, mapped network drives.' 'Identifies USB/network volumes and acquisition targets.' -Quick $true)
    (N 'mountvol' 'Volume Mount Points (mountvol)' 'Sys' 'mountvol.exe' @() 'Lists volume GUIDs and mount points.' 'Maps volumes to GUIDs seen in artifacts.')
    (N 'driverquery' 'Installed Drivers (driverquery)' 'Sys' 'driverquery.exe' @('/v','/fo','csv') 'Loaded/installed drivers with paths and dates.' 'Rogue or vulnerable drivers.' -Ext 'csv' -Timeout 180)
    (S 'installedsw' 'Installed Applications' 'Sys' { $k='HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*','HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*','HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*'; Get-ItemProperty $k -ErrorAction SilentlyContinue | Where-Object DisplayName | Select-Object DisplayName,DisplayVersion,Publisher,InstallDate,InstallLocation,UninstallString | Sort-Object DisplayName } 'Software inventory from Uninstall registry keys.' 'Unexpected remote-admin tools, archivers, tunnelling tools.')
    (S 'defender' 'Windows Defender Status and Detections' 'Sys' { Get-MpComputerStatus | Select-Object AMServiceEnabled,AntivirusEnabled,RealTimeProtectionEnabled,AntivirusSignatureVersion,AntivirusSignatureLastUpdated,QuickScanEndTime,FullScanEndTime; Get-MpThreatDetection | Select-Object DetectionID,ThreatID,InitialDetectionTime,ProcessName,Resources,DomainUser,ActionSuccess } 'Defender health and recorded threat detections (read-only Get-Mp* cmdlets).' 'Shows whether protection was disabled and what Defender already detected.' -Quick $true)
    # ---- Network ----
    (N 'ipconfig' 'Network Configuration (ipconfig /all)' 'Net' 'ipconfig.exe' @('/all') 'Interfaces, IPs, gateways, DNS servers, DHCP, MAC.' 'Network identity of the host.' -Quick $true)
    (N 'arp' 'ARP Cache (arp -a)' 'Net' 'arp.exe' @('-a') 'Recently contacted local hosts.' 'Local lateral movement leads.' -Quick $true)
    (N 'route' 'Routing Table (route print)' 'Net' 'route.exe' @('print') 'IPv4/IPv6 routes.' 'Rogue routes or VPN/tunnel adapters.' -Quick $true)
    (N 'netstat' 'Network Connections (netstat -ano)' 'Net' 'netstat.exe' @('-ano') 'Active TCP/UDP connections and listening ports with owning PID (human-readable).' 'C2 and lateral movement connections.' -Quick $true)
    (S 'netconn' 'Network Connections - structured (CSV/JSON)' 'Net' { $pn=@{}; $pp=@{}; Get-CimInstance Win32_Process | ForEach-Object { $pn[[int]$_.ProcessId]=$_.Name; $pp[[int]$_.ProcessId]=$_.ExecutablePath }
        Get-NetTCPConnection | ForEach-Object { [pscustomobject]@{ Proto='TCP'; LocalAddress=$_.LocalAddress; LocalPort=$_.LocalPort; RemoteAddress=$_.RemoteAddress; RemotePort=$_.RemotePort; State=$_.State; PID=$_.OwningProcess; Process=$pn[[int]$_.OwningProcess]; ProcessPath=$pp[[int]$_.OwningProcess]; Created=$_.CreationTime } }
        Get-NetUDPEndpoint | ForEach-Object { [pscustomobject]@{ Proto='UDP'; LocalAddress=$_.LocalAddress; LocalPort=$_.LocalPort; RemoteAddress=''; RemotePort=''; State=''; PID=$_.OwningProcess; Process=$pn[[int]$_.OwningProcess]; ProcessPath=$pp[[int]$_.OwningProcess]; Created=$_.CreationTime } } } 'TCP/UDP connections joined to process name and path, as CSV and JSON.' 'Pivot from network to process.' -Quick $true)
    (S 'listening' 'Listening Ports' 'Net' { $pn=@{}; Get-CimInstance Win32_Process | ForEach-Object { $pn[[int]$_.ProcessId]=$_.ExecutablePath }; Get-NetTCPConnection -State Listen | ForEach-Object { [pscustomobject]@{ Proto='TCP'; Address=$_.LocalAddress; Port=$_.LocalPort; PID=$_.OwningProcess; Path=$pn[[int]$_.OwningProcess] } }; Get-NetUDPEndpoint | ForEach-Object { [pscustomobject]@{ Proto='UDP'; Address=$_.LocalAddress; Port=$_.LocalPort; PID=$_.OwningProcess; Path=$pn[[int]$_.OwningProcess] } } } 'Listening TCP/UDP sockets with owning executable.' 'Backdoors, unexpected services.' -Quick $true)
    (N 'dnscache' 'DNS Cache (ipconfig /displaydns)' 'Net' 'ipconfig.exe' @('/displaydns') 'Cached DNS names resolved by the host (volatile).' 'Recently resolved domains - C2/phishing leads.' -Quick $true)
    (S 'netif' 'IP Configuration - structured' 'Net' { Get-NetIPConfiguration | ForEach-Object { [pscustomobject]@{ Interface=$_.InterfaceAlias; IPv4=($_.IPv4Address.IPAddress -join ';'); IPv6=($_.IPv6Address.IPAddress -join ';'); Gateway=($_.IPv4DefaultGateway.NextHop -join ';'); DNS=($_.DnsServer.ServerAddresses -join ';') } } } 'Interfaces, addresses, gateways, DNS servers (CSV/JSON).' 'Structured companion to ipconfig.')
    (N 'netshares' 'Network Shares and Sessions (net share / net use)' 'Net' 'cmd.exe' @('/c','net share & net use & net session') 'Local shares, mapped drives, inbound sessions (net session needs admin).' 'Data staging and lateral movement.' -Admin 'partial')
    (N 'firewall' 'Firewall Profiles (netsh)' 'Net' 'netsh.exe' @('advfirewall','show','allprofiles') 'Windows Firewall state per profile.' 'Detects disabled firewall.')
    (N 'hostsfile' 'Hosts File' 'Net' 'cmd.exe' @('/c','type','%SystemRoot%\System32\drivers\etc\hosts') 'Contents of the hosts file.' 'Name-resolution tampering.')
    # ---- Processes / services ----
    (N 'tasklist_v' 'Running Processes (tasklist /v)' 'Proc' 'tasklist.exe' @('/v') 'Processes with user, status, window title.' 'Process overview.' -Quick $true)
    (N 'tasklist_svc' 'Processes and Services (tasklist /svc)' 'Proc' 'tasklist.exe' @('/svc') 'Maps PIDs to hosted services.' 'Services inside svchost.' -Quick $true)
    (S 'processes' 'Processes - PID, PPID, path, command line' 'Proc' { $ps=Get-CimInstance Win32_Process; $nm=@{}; $ps | ForEach-Object { $nm[[int]$_.ProcessId]=$_.Name }
        $ps | ForEach-Object { [pscustomobject]@{ PID=$_.ProcessId; PPID=$_.ParentProcessId; ParentName=$nm[[int]$_.ParentProcessId]; Name=$_.Name; Path=$_.ExecutablePath; CommandLine=$_.CommandLine; CreationDate=$_.CreationDate; SessionId=$_.SessionId } } | Sort-Object PID } 'Full process list from WMI. Paths/command lines of other users need administrator.' 'Process tree and command lines are core triage data.' -Admin 'partial' -Quick $true -Sensitive $true)
    (S 'services' 'Services with Executable Paths' 'Proc' { Get-CimInstance Win32_Service | Select-Object Name,DisplayName,State,StartMode,StartName,PathName,ProcessId,Description } 'All services with binary path, account, start mode.' 'Service-based persistence and malicious services.' -Quick $true)
    (N 'sc_query' 'Service Controller (sc query)' 'Proc' 'sc.exe' @('query','state=','all') 'Raw service states from the SCM.' 'Cross-check against WMI view.' -Timeout 180)
    (N 'schtasks' 'Scheduled Tasks (verbose)' 'Proc' 'schtasks.exe' @('/query','/fo','LIST','/v') 'All scheduled tasks with actions and triggers.' 'Task-based persistence.' -Timeout 240 -Quick $true)
    (S 'startup' 'Startup Entries (Run keys, startup folders)' 'Proc' { Get-CimInstance Win32_StartupCommand | Select-Object Name,Command,Location,User } 'Startup commands known to WMI.' 'Autostart persistence.' -Quick $true)
    # ---- Users / auth ----
    (N 'whoami' 'Current User, Groups, Privileges (whoami /all)' 'Auth' 'whoami.exe' @('/all') 'Identity of the account running the collection and its privileges.' 'Documents collection context.' -Quick $true)
    (N 'query_user' 'Logged-on Users (query user)' 'Auth' 'query.exe' @('user') 'Interactive and RDP sessions. Exit code 1 means no sessions.' 'Who is on the host now.' -Quick $true)
    (N 'qwinsta' 'Sessions (qwinsta)' 'Auth' 'qwinsta.exe' @() 'Terminal Services/RDP session table.' 'Remote sessions.' -Quick $true)
    (N 'net_user' 'Local Users (net user)' 'Auth' 'net.exe' @('user') 'Local accounts.' 'Rogue accounts.' -Quick $true)
    (N 'net_localgroup' 'Local Groups (net localgroup)' 'Auth' 'net.exe' @('localgroup') 'Local groups.' 'Group inventory.' -Quick $true)
    (N 'net_admins' 'Local Administrators' 'Auth' 'net.exe' @('localgroup','administrators') 'Members of Administrators.' 'Privilege abuse.' -Quick $true)
    (S 'localusers' 'Local Users - detailed' 'Auth' { Get-LocalUser | Select-Object Name,Enabled,LastLogon,PasswordLastSet,PasswordRequired,AccountExpires,SID,Description } 'Accounts with last logon and password-set times.' 'Recent account creation or odd enablement.' -Quick $true)
    (N 'netcfgws' 'Workstation/Domain Config (net config workstation)' 'Auth' 'net.exe' @('config','workstation') 'Domain, logon domain, workstation settings.' 'Domain context.' -Quick $true)
    )
}
